import { derived, writable } from "svelte/store";

export interface CartLine {
    sku: string;
    quantity: number;
}

function loadSaved(): CartLine[] {
    if (typeof localStorage === "undefined") {
        return [];
    }
    const raw = localStorage.getItem("cart");
    if (raw === null) {
        return [];
    }
    try {
        const parsed = JSON.parse(raw) as CartLine[];
        return Array.isArray(parsed) ? parsed : [];
    } catch {
        return [];
    }
}

export const cart = writable<CartLine[]>(loadSaved());

export const itemCount = derived(cart, function count(lines) {
    return lines.reduce(function total(sum, line) {
        return sum + line.quantity;
    }, 0);
});

export function addLine(line: CartLine): void {
    cart.update(function append(lines) {
        return [...lines, line];
    });
}
